function validate([root1, root2]) {
  for (const [name, root] of [['root1', root1], ['root2', root2]]) {
    if (root.length > 0 && root[0] === null) return `${name}: use [] for an empty tree.`;
    if (root.some(v => v !== null && (v < -100000 || v > 100000))) return `${name}: node values are between -10^5 and 10^5.`;
    // Each node keeps the open interval its subtree must stay inside.
    const nodes = root.length ? [{ val: root[0], below: -Infinity, above: Infinity }] : [];
    let index = 1;
    for (let head = 0; index < root.length; head++) {
      if (head >= nodes.length) return `${name}: the level order has values with no parent node.`;
      const node = nodes[head];
      const left = root[index];
      const right = index + 1 < root.length ? root[index + 1] : null;
      if (left !== null) {
        if (left <= node.below || left >= node.val) return `${name} must be a binary search tree: smaller values on the left, larger on the right.`;
        nodes.push({ val: left, below: node.below, above: node.val });
      }
      if (right !== null) {
        if (right <= node.val || right >= node.above) return `${name} must be a binary search tree: smaller values on the left, larger on the right.`;
        nodes.push({ val: right, below: node.val, above: node.above });
      }
      index += 2;
    }
    if (nodes.length > 5000) return `${name} has at most 5000 nodes.`;
  }
  return null;
}

