function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const large = size === 'large';
  const makeTree = (n, low, high) => {
    if (n === 0) return [];
    // A partial shuffle of low..high picks n distinct values.
    const pool = Array.from({ length: high - low + 1 }, (_, i) => low + i);
    for (let i = 0; i < n; i++) { const j = i + pick(pool.length - i); [pool[i], pool[j]] = [pool[j], pool[i]]; }
    const sorted = pool.slice(0, n).sort((a, b) => a - b);
    // The insertion order decides the shape: random, ascending chain, descending chain or balanced.
    const style = pick(4);
    let order;
    if (style === 0) {
      order = sorted.slice();
      for (let i = order.length - 1; i > 0; i--) { const j = pick(i + 1); [order[i], order[j]] = [order[j], order[i]]; }
    } else if (style === 1) order = sorted.slice();
    else if (style === 2) order = sorted.slice().reverse();
    else {
      order = [];
      const ranges = [[0, n - 1]];
      for (let head = 0; head < ranges.length; head++) {
        const [lo, hi] = ranges[head];
        if (lo > hi) continue;
        const mid = (lo + hi) >> 1;
        order.push(sorted[mid]);
        ranges.push([lo, mid - 1], [mid + 1, hi]);
      }
    }
    const top = { val: order[0], left: null, right: null };
    for (let i = 1; i < order.length; i++) {
      let node = top;
      for (;;) {
        const side = order[i] < node.val ? 'left' : 'right';
        if (!node[side]) { node[side] = { val: order[i], left: null, right: null }; break; }
        node = node[side];
      }
    }
    const out = [];
    const queue = [top];
    for (let head = 0; head < queue.length; head++) {
      const node = queue[head];
      if (!node) { out.push(null); continue; }
      out.push(node.val);
      queue.push(node.left, node.right);
    }
    while (out[out.length - 1] === null) out.pop();
    return out;
  };
  const range = () => {
    if (large) return rand() < 0.3 ? [-3000, 3000] : [-100000, 100000];
    const roll = rand();
    if (roll < 0.5) return [-6, 10];
    if (roll < 0.8) return [-100000, 100000];
    return [99990, 100000];
  };
  const count = () => (large ? 900 + pick(100) : rand() < 0.15 ? 0 : 1 + pick(8));
  const [low1, high1] = range();
  const [low2, high2] = rand() < 0.6 ? [low1, high1] : range();
  return [makeTree(Math.min(count(), high1 - low1 + 1), low1, high1), makeTree(Math.min(count(), high2 - low2 + 1), low2, high2)];
}
